require_once __DIR__.'/functions.php';require_login();$pageTitle='Laporan';
$rows=$pdo->query("SELECT l.*,b.name borrower,COALESCE(p.paid,0) paid FROM loans l JOIN borrowers b ON b.id=l.borrower_id LEFT JOIN (SELECT loan_id,SUM(amount) paid FROM payments GROUP BY loan_id) p ON p.loan_id=l.id ORDER BY l.due_date")->fetchAll();
