<section class="panel"><div class="panelhead"><h2>Laporan pinjaman</h2><button class="btn secondary" onclick="window.print()">Cetak / Simpan PDF</button></div><form class="toolbar" method="get"><select name="status"><option value="">Semua status</option><?php foreach(['Belum jatuh tempo','Jatuh tempo hari ini','Terlambat','Lunas'] as $s):?><option value="<?=e($s)?>" <?=$filter===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="tablewrap" style="margin-top:15px"><table><tr><th>Kode</th><th>Peminjam</th><th>Jatuh tempo</th><th>Pokok</th><th>Bunga</th><th>Total</th><th>Dibayar</th><th>Sisa</th><th>Status</th></tr><?php $n=0;$sum=0;foreach($rows as $r):$st=loan_status($r,(float)$r['paid']);if($filter&&$filter!==$st)continue;$n++;$left=max(0,(float)$r['total_due']-(float)$r['paid']);$sum+=$left;?><tr><td><?=e($r['loan_code'])?></td><td><?=e($r['borrower'])?></td><td><?=date('d/m/Y',strtotime($r['due_date']))?></td><td><?=rupiah($r['principal'])?></td><td><?=rupiah($r['interest_amount'])?></td><td><?=rupiah($r['total_due'])?></td><td><?=rupiah($r['paid'])?></td><td><?=rupiah($left)?></td><td><?=e($st)?></td></tr><?php endforeach;?></table></div><p><b>Jumlah data:</b> <?=$n?> &nbsp; <b>Total sisa tagihan:</b> <?=rupiah($sum)?></p></section><style>@media print{.sidebar,.topbar,.btn,.toolbar{display:none!important}.main{margin:0;padding:0}.panel{border:0;box-shadow:none}}</style>
